   env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0:halt_on_error=1',UBSAN_OPTIONS='halt_on_error=1');q=subprocess.run(['taskset','-c','8',str(p/'check')],capture_output=True,text=True,env=env);(p/f'{tag}.run.log').write_text(q.stdout+q.stderr);row['run']=q.returncode
  out.append(row);(p/'checks-final2.json').write_text(json.dumps(out,indent=2)+'\n');print(tag,row.get('run',row['build']),flush=True)
