with open('/tmp/sirkit_performance_cpu8.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc,native in [('gcc',False),('gcc',True),('clang',False),('clang',True)]:
  for typ in ['std::int32_t','float']:
   for v in variants:
    cmd=['taskset','-c','8','/usr/bin/g++'if cc=='gcc'else'clang++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DHEADER="{p/("rotate_"+v+".hpp")}"',f'-DTYPE={typ}',str(p/'rotate_bench.cpp'),'-o',str(p/f'rotate-{cc}-{native}-{typ}-{v}')]
    if cc=='clang':cmd+=['--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']
    if native:cmd+=['-march=native']
    q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr
   for h,w in [(256,256),(1024,1024),(2048,2048),(64,16384),(16384,64),(1025,1027)]:
    for mode in [0,1,2]:
     for rep in range(7):
      order=variants+['control'];rng.shuffle(order)
      for v in order:
       src=p/f'rotate-{cc}-{native}-{typ}-{("baseline"if v=="control"else v)}';target=p/'run';target.write_bytes(src.read_bytes());target.chmod(0o755)
       q=subprocess.run(['taskset','-c','8',str(target),str(h),str(w),str(mode)],capture_output=True,text=True);assert q.returncode==0,(cc,native,typ,v,h,w,mode,q.stderr)
       ns,ch=map(int,q.stdout.split());raw.append(dict(cc=cc,native=native,typ=typ,h=h,w=w,mode=mode,rep=rep,v=v,ns=ns,ch=ch))
     rows=[x for x in raw if(x['cc'],x['native'],x['typ'],x['h'],x['w'],x['mode'])==(cc,native,typ,h,w,mode)];assert len({x['ch']for x in rows})==1
     m={v:statistics.median(x['ns']for x in rows if x['v']==v)for v in variants+['control']};print(cc,native,typ,h,w,mode,{v:round(m[v]/m['baseline'],3)for v in m},flush=True);(p/'rotate-32final-raw.json').write_text(json.dumps(raw)+'\n')

